parameters.jsCode:
// Maps the AI reading of the note onto exactly the fields Sergii's WF-A accepts (unknown fields would be rejected there).
const ERLAUBT = {
  training_interest: ['leadership', 'communication', 'sales', 'project_management', 'digital_skills', 'ai_automation', 'other'],
  budget_status: ['approved', 'planned', 'unknown', 'not_disclosed', 'no_budget'],
  follow_up: ['within_one_week', 'within_two_weeks', 'within_one_month', 'on_date', 'no_follow_up', 'not_decided'],
};
const ai = $json.output && typeof $json.output === 'object' ? $json.output : {};
const notiz = $('Eingabe vereinheitlichen').first().json.notiz;
const text = (v, max) => {
  const s = typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : '';
  return s && s.toLowerCase() !== 'null' ? s.slice(0, max) : null;
};
const wahl = (v, liste) => (liste.includes(v) ? v : null);

let email = text(ai.email, 254);
if (email) email = email.toLowerCase();
if (email && !/^[^\s@]+@[^\s@]+\.[a-z]{2,63}$/i.test(email)) email = null;
let phone = text(ai.phone, 40);
if (phone) {
  const ziffern = phone.replace(/\D/g, '').length;
  if (ziffern < 7 || ziffern > 20) phone = null;
}
let website = text(ai.website, 2048);
if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;
if (website && !/^https?:\/\/[^\s\/?#@]+\.[a-z]{2,63}([\/?#]|$)/i.test(website)) website = null;
let follow_up = wahl(ai.follow_up, ERLAUBT.follow_up);
let follow_up_date = /^\d{4}-\d{2}-\d{2}$/.test(ai.follow_up_date || '') ? ai.follow_up_date : null;
if (follow_up === 'on_date' && !follow_up_date) follow_up = 'not_decided';
if (follow_up !== 'on_date') follow_up_date = null;

const firma = text(ai.company_name, 200);
if (!firma) {
  return [{ json: { ok: false, output: '⚠️ Ich konnte in der Notiz **keinen Firmennamen** erkennen. Bitte schick sie noch einmal mit dem Namen der Firma, z. B. „Traf Lisa Weber von dm-drogerie markt …“.\n\nEs wurde nichts gespeichert.' } }];
}

return [{
  json: {
    ok: true,
    payload: {
      source: 'internal_form',
      company_name: firma,
      contact_name: text(ai.contact_name, 160),
      email,
      phone,
      website,
      training_interest: wahl(ai.training_interest, ERLAUBT.training_interest),
      budget_status: wahl(ai.budget_status, ERLAUBT.budget_status),
      follow_up,
      follow_up_date,
      notes: notiz.slice(0, 10000),
      submission_id: 'messe-hub-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10),
    },
  },
}];

// Turns WF-A's HTTP answer into the chat reply (Markdown is rendered by the Messe-Hub).
const INTERESSE = { leadership: 'Führung', communication: 'Kommunikation', sales: 'Vertrieb', project_management: 'Projektmanagement', digital_skills: 'Digitale Kompetenzen', ai_automation: 'KI & Automatisierung', other: 'Sonstiges' };
const BUDGET = { approved: 'Genehmigt', planned: 'Geplant', unknown: 'Unklar', not_disclosed: 'Nicht genannt', no_budget: 'Kein Budget' };
const FOLLOW_UP = { within_one_week: 'Innerhalb 1 Woche', within_two_weeks: 'Innerhalb 2 Wochen', within_one_month: 'Innerhalb 1 Monat', on_date: 'Zum Termin', no_follow_up: 'Kein Follow-up', not_decided: 'Noch offen' };
const DUPLIKAT = {
  NEW: 'Neu – kein bekannter Eintrag',
  POSSIBLE_DUPLICATE: '⚠️ Mögliches Duplikat – bitte im Dashboard unter „Duplikate“ prüfen',
  EXISTING_CONTACT: '🔁 Bekannter Kontakt – dem vorhandenen Kontakt zugeordnet',
};
const p = $('Anfrage für WF-A bauen').first().json.payload;
const status = $json.statusCode;
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const oder = (v) => v || '–';

if ((status === 201 || status === 200) && body.success === true) {
  const zeilen = [
    '✅ **Lead gespeichert: ' + p.company_name + '**',
    '',
    '- **Lead-ID:** ' + body.lead_id + (body.idempotent_replay ? ' (war schon gespeichert)' : ''),
    '- **Kontakt:** ' + oder(p.contact_name) + ' · ' + oder(p.email) + ' · ' + oder(p.phone),
    '- **Training:** ' + oder(INTERESSE[p.training_interest]) + ' · **Budget:** ' + oder(BUDGET[p.budget_status]) + ' · **Follow-up:** ' + oder(FOLLOW_UP[p.follow_up]) + (p.follow_up_date ? ' (' + p.follow_up_date + ')' : ''),
    '- **Duplikatprüfung:** ' + (DUPLIKAT[body.status] || body.status),
    '',
    'Firmenrecherche, KI-Auswertung und Bewertung laufen jetzt automatisch in Sergiis Workflow (ca. 1–2 Minuten). Der Bericht kommt per E-Mail, das Dashboard aktualisiert sich von selbst.',
  ];
  return [{ json: { output: zeilen.join('\n') } }];
}

let grund;
if (status === 401 || status === 403) grund = 'Zugriff auf Sergiis Eingang verweigert – der „Trade Fair Webhook Key“ passt nicht zu WF-A.';
else if (status === 404) grund = 'Sergiis Eingangs-Workflow (WF-A Lead Capture) ist nicht aktiv. Bitte in n8n aktivieren.';
else if (status === 400 || status === 422 || status === 409) {
  const fehler = body.error || {};
  const details = Array.isArray(fehler.details) ? fehler.details.map((d) => (d.field || '') + (d.code ? ' (' + d.code + ')' : '')).filter(Boolean) : [];
  grund = 'Sergiis Eingang hat die Daten abgelehnt: ' + (fehler.message || fehler.code || 'ungültige Angaben') + (details.length ? ' – ' + details.join(', ') : '');
} else if (!Number.isInteger(status)) grund = 'Sergiis Eingang war nicht erreichbar.';
else grund = 'Sergiis Eingang meldet Fehler ' + status + '.';

return [{ json: { output: '❌ **Nicht gespeichert.** ' + grund + '\n\nDeine Notiz ist nicht verloren – schick sie einfach noch einmal, sobald das Problem behoben ist.' } }];
